-- M16 document attachments and the private attachments bucket (Plan P6.2; Spec FR-10, §9.4)
--
-- Files live in a private Storage bucket; their metadata lives here. Paths are generated by the
-- server as {owner_id}/{document_id}/{uuid}-{sanitized-name}, so a user only ever writes inside
-- their own folder, and only to a path that was registered here first. Downloads use short-lived
-- signed URLs created for the signed-in owner. No SVG or HTML: nothing uploaded can run as app
-- content, and files are served from the Storage origin as downloads.

create table public.document_attachments (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  document_id uuid not null,
  storage_path text not null,
  -- Display name (the original, cleaned). The stored object name is the sanitized one in the path.
  file_name public.no_secret_text not null check (char_length(btrim(file_name)) between 1 and 255),
  mime_type text not null check (mime_type in (
    'application/pdf', 'image/png', 'image/jpeg', 'image/webp', 'image/gif',
    'text/plain', 'text/markdown', 'text/csv', 'application/json'
  )),
  size_bytes bigint not null check (size_bytes between 1 and 10485760),
  created_at timestamptz not null default now(),

  constraint document_attachments_document_owner_fkey foreign key (document_id, owner_id)
    references public.documents (id, owner_id) on delete cascade,
  constraint document_attachments_storage_path_key unique (storage_path),
  -- Inside the owner's and the document's folder, with a generated object name.
  constraint document_attachments_path_shape check (
    storage_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}-[A-Za-z0-9._-]{1,120}$'
    and starts_with(storage_path, owner_id::text || '/' || document_id::text || '/')
  )
);

comment on table public.document_attachments is
  'Metadata for files in the private attachments bucket. Objects are removed by the app when rows go.';

create index document_attachments_document_idx on public.document_attachments (document_id, created_at);

create or replace function private.document_attachments_activity()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc record;
begin
  if tg_op = 'INSERT' then
    select title, project_id into v_doc from public.documents where id = new.document_id;
    perform private.record_activity(new.owner_id, v_doc.project_id, null, 'attachment.added',
      'Attached ' || new.file_name || ' to ' || coalesce(v_doc.title, 'a document'),
      jsonb_build_object('document_id', new.document_id, 'file_name', new.file_name,
        'mime_type', new.mime_type, 'size_bytes', new.size_bytes));
    return new;
  end if;

  -- Only a deliberate removal: skip when the document (or its owner or project) is going too.
  select title, project_id into v_doc from public.documents where id = old.document_id;
  if v_doc.title is not null then
    perform private.record_activity(old.owner_id, v_doc.project_id, null, 'attachment.removed',
      'Removed ' || old.file_name || ' from ' || v_doc.title,
      jsonb_build_object('document_id', old.document_id, 'file_name', old.file_name));
  end if;
  return old;
end;
$$;

create trigger document_attachments_activity
  after insert or delete on public.document_attachments
  for each row execute function private.document_attachments_activity();

alter table public.document_attachments enable row level security;

create policy "document_attachments: owner can read" on public.document_attachments
  for select to authenticated using ((select auth.uid()) = owner_id);
create policy "document_attachments: owner can insert" on public.document_attachments
  for insert to authenticated with check ((select auth.uid()) = owner_id);
create policy "document_attachments: owner can delete" on public.document_attachments
  for delete to authenticated using ((select auth.uid()) = owner_id);

revoke all on table public.document_attachments from anon, authenticated;
grant select, delete on table public.document_attachments to authenticated;
-- No update: an attachment is replaced by removing it and uploading again.
grant insert (document_id, storage_path, file_name, mime_type, size_bytes)
  on table public.document_attachments to authenticated;
grant select, insert, update, delete on table public.document_attachments to service_role;

------------------------------------------------------------------------------
-- Private bucket: 10 MB, an allowlist of document and image types (no SVG, no HTML).
------------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'attachments', 'attachments', false, 10485760,
  array[
    'application/pdf', 'image/png', 'image/jpeg', 'image/webp', 'image/gif',
    'text/plain', 'text/markdown', 'text/csv', 'application/json'
  ]
)
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

-- Storage RLS: the first path segment is the owner's id. Upload also needs the metadata row for
-- that exact path (written first by the server action), so only server-generated paths are used.
-- No update policy: objects can't be overwritten.
create policy "attachments: owner can read own files" on storage.objects
  for select to authenticated
  using (bucket_id = 'attachments' and (storage.foldername(name))[1] = (select auth.uid())::text);

create policy "attachments: owner can upload registered files" on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'attachments'
    and (storage.foldername(name))[1] = (select auth.uid())::text
    and exists (
      select 1 from public.document_attachments a
      -- "name" is storage.objects.name (document_attachments has no such column).
      where a.storage_path = name and a.owner_id = (select auth.uid())
    )
  );

create policy "attachments: owner can delete own files" on storage.objects
  for delete to authenticated
  using (bucket_id = 'attachments' and (storage.foldername(name))[1] = (select auth.uid())::text);
